public ListNode? MiddleNodeTwoPass(ListNode? head)
{
    int length = 0;
    ListNode? curr = head;
    while (curr != null) { length++; curr = curr.Next; }
    int mid = length / 2;
    curr = head;
    for (int i = 0; i < mid; i++) curr = curr!.Next;
    return curr;
}

public ListNode? MiddleNode(ListNode? head)
{
    ListNode slow = head, fast = head;
    while (fast != null && fast.Next != null)
    {
        slow = slow.Next!;
        fast = fast.Next.Next!;
    }
    return slow;
}
